--
-- Table structure for table `complaints`
--

DROP TABLE IF EXISTS `complaints`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `complaints` (
  `id` varchar(22) NOT NULL,
  `action_taken` text,
  `category` enum('ELECTRICAL','IT','MECHANICAL','OTHER') NOT NULL,
  `close_time` datetime(6) DEFAULT NULL,
  `code` varchar(255) NOT NULL,
  `description` text,
  `image_after` varchar(255) DEFAULT NULL,
  `image_before` varchar(255) DEFAULT NULL,
  `priority` enum('HIGH','LOW','MEDIUM') NOT NULL,
  `report_date` datetime(6) NOT NULL,
  `status` enum('CLOSED','OPEN','PENDING','CREATED','REJECTED') NOT NULL,
  `subject` varchar(255) DEFAULT NULL,
  `total_time_minutes` int DEFAULT NULL,
  `updated_at` datetime(6) NOT NULL,
  `reporter` varchar(22) DEFAULT NULL,
  `assignee` varchar(22) DEFAULT NULL,
  `area_code` varchar(22) DEFAULT NULL,
  `equipment_code` varchar(22) DEFAULT NULL,
  `created_at` datetime(6) DEFAULT NULL,
  `created_by` varchar(22) DEFAULT NULL,
  `updated_by` varchar(22) DEFAULT NULL,
  `reassigned_at` datetime(6) DEFAULT NULL,
  `previous_assignee` varchar(22) DEFAULT NULL,
  `approval_date` datetime(6) DEFAULT NULL,
  `approval_remarks` text,
  `is_approved` tinyint(1) NOT NULL DEFAULT '0',
  `rejection_reason` text,
  `approved_by` varchar(22) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `UK4qh8y24fq3k37yqmvuwsgapfl` (`code`),
  KEY `FK_complaints_reporter` (`reporter`),
  KEY `FK_complaints_assignee` (`assignee`),
  KEY `FK_complaints_area` (`area_code`),
  KEY `FKcssytgfsdfsv9lda6vcmbus6h` (`created_by`),
  KEY `FK4tgkw1chucnpnn9uyfh0boewf` (`updated_by`),
  KEY `idx_c_equipment_code` (`equipment_code`),
  KEY `FKlhasnddyayrnxy2owyokhk115` (`previous_assignee`),
  KEY `FKjwtw1kw6f6ijct1cwt22jjp5w` (`approved_by`),
  CONSTRAINT `FK4tgkw1chucnpnn9uyfh0boewf` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`),
  CONSTRAINT `FK_complaints_area` FOREIGN KEY (`area_code`) REFERENCES `areas` (`id`),
  CONSTRAINT `FK_complaints_assignee` FOREIGN KEY (`assignee`) REFERENCES `users` (`id`),
  CONSTRAINT `FK_complaints_equipment` FOREIGN KEY (`equipment_code`) REFERENCES `equipments` (`id`),
  CONSTRAINT `FK_complaints_reporter` FOREIGN KEY (`reporter`) REFERENCES `users` (`id`),
