--
-- Table structure for table `work_reports`
--

DROP TABLE IF EXISTS `work_reports`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `work_reports` (
  `id` varchar(22) NOT NULL,
  `category` enum('BREAKDOWN','CORRECTIVE_MAINTENANCE','OTHER','PREVENTIVE_MAINTENANCE') NOT NULL,
  `code` varchar(255) NOT NULL,
  `problem` text NOT NULL,
  `remark` text,
  `report_date` date NOT NULL,
  `scope` enum('ELECTRICAL','IT','MECHANICAL','OTHER') NOT NULL,
  `shift` enum('DAY','NIGHT') NOT NULL,
  `solution` text,
  `start_time` datetime(6) NOT NULL,
  `status` enum('CLOSED','OPEN','PENDING') NOT NULL,
  `stop_time` datetime(6) DEFAULT NULL,
  `total_time_minutes` int DEFAULT NULL,
  `updated_at` datetime(6) NOT NULL,
  `work_type` varchar(255) DEFAULT NULL,
  `supervisor` varchar(22) DEFAULT NULL,
  `area_code` varchar(22) DEFAULT NULL,
  `equipment_code` varchar(22) DEFAULT NULL,
  `created_at` datetime(6) DEFAULT NULL,
  `created_by` varchar(22) DEFAULT NULL,
  `updated_by` varchar(22) DEFAULT NULL,
  `issue_root_id` varchar(22) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `UK2pl0lg83anrhlwyhw3uuajdlc` (`code`),
  KEY `FK_work_reports_supervisor` (`supervisor`),
  KEY `FK_work_reports_area` (`area_code`),
  KEY `FK9fb6yunt3supy69w2autad2q` (`created_by`),
  KEY `FKd0n1sy38lbqlgsob4mad6r7p9` (`updated_by`),
  KEY `idx_wr_equipment_code` (`equipment_code`),
  CONSTRAINT `FK9fb6yunt3supy69w2autad2q` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`),
  CONSTRAINT `FK_work_reports_area` FOREIGN KEY (`area_code`) REFERENCES `areas` (`id`),
  CONSTRAINT `FK_work_reports_equipment` FOREIGN KEY (`equipment_code`) REFERENCES `equipments` (`id`),
  CONSTRAINT `FK_work_reports_supervisor` FOREIGN KEY (`supervisor`) REFERENCES `users` (`id`),
  CONSTRAINT `FKd0n1sy38lbqlgsob4mad6r7p9` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

